  for (let i = 0; i < n; i++) {
    let th;
    if (o.front) th = (i / (n - 1) - 0.5) * o.front * 2 + (rnd() - 0.5) * (o.front / n);
    else th = i * 2.39996 + (rnd() - 0.5) * 0.25;
