    if (nativeRule?.supported === false) { this.menus?.toast?.(nativeRule.name + '：' + nativeRule.reason); return false; }
    const unavailable = UNAVAILABLE_NATIVE_STAGES.find(stage => stage.id === (o.mapId || this.mapDef?.id));
    if (unavailable) { this.menus?.toast?.(unavailable.name + '：' + unavailable.reason); return false; }
    const flow = this._beginMatchFlow();
    try { return await this.startMatch(o, flow); }
    catch (error) {
