    const selectedShotState=await selectedShotReady;
    if (!flow.current()) return;
    if(selectedShotState.error)throw selectedShotState.error;
    G.music?.stop?.(0.3); this._musicTrack = null;
    this.showcase.hide();
    if (!flow.current()) return;
    if (this.match) this.match.dispose();
    if (!flow.current()) return;
