  }

  pause() {
    if (!this.match || this.match.attract || this.match.paused) return;
    // only a live round (or its intro) can pause — never on top of time's up / judge / results
    if (this.match.state !== 'playing' && this.match.state !== 'intro') return;
    if (G.netm) {   // online: the match carries on underneath the menu
      this.input.exitLock();
      if (this.match.controller) { this.match.controller.cancelForMenuTakeover?.(); this.match.controller.menuBlocked = true; this.match.controller.enabled = false; }
      this.menus?.show('pause');
      return;
    }
    this.match.controller?.cancelForMenuTakeover?.();
    this.match.paused = true;
    this.input.exitLock();
    this.menus?.show('pause');
    G.audio?.duck?.(0.5, 99);
  }
  resume() {
    if (!this.match) return;
    this.menus?.show(null);
    this.match.paused = false;
    // Reports can arrive while offline simulation is paused; retire them at resume too.
    try { this.input.s3ControllerMotionReader?.discard?.(); } catch {}
    if (this.match.controller) { this.match.controller.menuBlocked = false; this.match.controller.enabled = true; }
    this.input.requestLock();
    G.audio?.duck?.(1, 0.01);
  }
  async quitToMenu() {
    const flow = this._beginMatchFlow();
    this._s3JudgeEpoch = (this._s3JudgeEpoch || 0) + 1;
    clearTimeout(this._netEndT);
    const leavingRoom = G.net && G.net.state !== 'offline' && G.net.state !== 'error';
    if (leavingRoom) flow.net.leave();
    if (this._matchFlow !== flow || this.match !== flow.match) return;
    if (leavingRoom && (G.net !== flow.net || G.net?.tr != null || G.net?.match != null || G.netm != null)) return;
    flow.captureRoom();
    this.input.exitLock();
    if (!flow.current()) return;
    this.menus?.show(null);
    if (!flow.current()) return;
    await this._fade(1, 350);
    if (!flow.current()) return;
    this.hud?.setVisible(false);
    this.hud?.hideSplatted?.();
    this.showcase.hide();
    G.mode = 'menu';
    this._setPalette(this._pickPalette());
    this._startAttract({ staticMenu: true });
    this.menus?.show('main');
    this._playMusic('menu');
    G.audio?.duck?.(1, 0.01);
    this._fade(0, 500);
    return this.match;
  }

  // Boss Battle intro: sweep in over the arena as HULLBREAKER bursts out of its home ground (boss time 1.8 s), hold on the
