    const judgeEpoch = this._s3JudgeEpoch = (this._s3JudgeEpoch || 0) + 1;
    const netm = G.netm, net = G.net, room = net?.tr;
    const presentationFlow = this._matchFlow;
    const resultsCurrent = () => this._matchFlow === presentationFlow && this.match === m && G.netm === netm && G.net === net && net?.tr === room;
    if (m.result?.mode === 'boss') return this._bossResults();
    this.hud?.hideSplatted?.();
    this.rig.overview();
    this.hud?.setVisible(true);
    const cov = m.result.coverage;
    const judgeP = this.hud?.judge({ colors: [G.teamHex[0], G.teamHex[1]], percents: [cov[0] * 100, cov[1] * 100], names: this.palette.names || TEAM_NAMES, winner: m.result.winner, isCurrent: resultsCurrent });
