    const before = { level: p.level, xp: p.xp, toNext: PROGRESSION.xpForLevel(p.level) };
    if (!privateBattle) {
      p.xp += gained; p.matches++; if (won) p.wins++; p.totalTurf += turf;
      settleProgression(p, PROGRESSION);
      saveJSON('inkwave.profile', p);
    }
    const data = {
      mode: m.result.mode, counts: m.result.counts, penalties: m.result.penalties, knockout: m.result.knockout, reason: m.result.reason,
      win: won, percents: [cov[0] * 100, cov[1] * 100], colors: [G.teamHex[0], G.teamHex[1]], teamNames: this.palette.names || TEAM_NAMES,
      players: m.actors.map((a) => ({ name: a.name, team: a.team, weapon: a.weaponId, turf: Math.round(a.stats.turf), splats: a.stats.splats + (a.stats.assists || 0), directSplats: a.stats.splats, assists: a.stats.assists || 0, deaths: a.stats.deaths, specials: a.stats.specials || 0, isSelf: a.isLocal, bot: !!a.isBot, disconnected: !!a.s3?.disconnected })),
      xp: { gained, levelBefore: before.level, levelAfter: p.level, xpBefore: before.xp, xpAfter: p.xp, xpToNextBefore: before.toNext, xpToNextAfter: PROGRESSION.xpForLevel(p.level) },
