  // ---------------------------------------------------------------------------------------- loop
  _loop() {
    requestAnimationFrame(this._iwRafCallback || (this._iwRafCallback = () => this._loop()));
    this.timer.update();
    const rawDt = this.timer.getDelta();
    // Cache URL flag once: diagnostics OFF has no repeated URL allocations.
    const probeEnabled = this.settings?.debugMode === true ||
      (this._iwProfilerQueryFlag ??= (typeof location !== 'undefined' &&
        new URLSearchParams(location.search).get('profileRange') === '1'));
    if (probeEnabled !== this._iwProfilerEnabled) {
      this._iwProfilerEnabled = probeEnabled;
      const epoch = this._iwProfilerEpoch = (this._iwProfilerEpoch || 0) + 1;
      this._rangeFrameProbe?.dispose?.();
      this._rangeFrameProbe = null;
      if (probeEnabled) import('../patches/local-quality/range-frame-profiler.mjs')
        .then(({ createFrameTimingProbe }) => {
          if (this._iwProfilerEnabled && this._iwProfilerEpoch === epoch)
            this._rangeFrameProbe = createFrameTimingProbe({ env: globalThis, game: this });
        })
        .catch(error => {
          if (this._iwProfilerEnabled && this._iwProfilerEpoch === epoch)
            console.warn('Optional range profiler unavailable:', error);
        });
    }
    this._rangeFrameProbe?.callback(rawDt);
    if (this.frozen) return;

    // Auto = battery-friendly 60 fps on touch hardware, native display refresh elsewhere.
    // Accumulate rAF time instead of dropping every Nth callback: 90 Hz therefore averages 60, not 45 fps.
    const fr = this.settings.frameRate ?? 'auto';
    let capHz = fr === 'display' ? 0 : fr === 60 ? 60 : (this.mobile?.touch ? 60 : 0);
    // Probe raw requestAnimationFrame timing once, without a second RAF loop.
    // Stable high-refresh touch panels use an even presentation divisor.
    if (fr === 'auto' && this.mobile?.touch) {
      this._iwRefreshProbe ||= createRefreshProbe();
      if (document.hidden) {
        if (!this._iwPacerHidden) this._iwRefreshProbe.reset();
        this._iwPacerHidden = true;
      } else {
        this._iwPacerHidden = false;
        capHz = evenTouchAutoHz(this._iwRefreshProbe.sample(rawDt));
      }
    }
    if (capHz !== this._iwLastCap) {
      this._frameCapAcc = 0;
      this._frameCapElapsed = 0;
      this._iwLastCap = capHz;
    }
    let dt = rawDt;
    if (capHz > 0) {
      const step = 1 / capHz;
      this._frameCapAcc = (this._frameCapAcc || 0) + rawDt;
      this._frameCapElapsed = (this._frameCapElapsed || 0) + rawDt;
      if (this._frameCapAcc + 1e-6 < step) { this._rangeFrameProbe?.skipped(); return; }
      this._frameCapAcc = Math.min(step, Math.max(0, this._frameCapAcc - step));
      dt = this._frameCapElapsed;
      this._frameCapElapsed = 0;
    } else {
      this._frameCapAcc = 0; this._frameCapElapsed = 0;
    }

    this.fpsAcc += dt; this.fpsN++;
    if (this.fpsAcc > 0.5) { this.fps = Math.round(this.fpsN / this.fpsAcc); this.fpsAcc = 0; this.fpsN = 0; }
    this._dynRes(dt);
    const frameStart = this._rangeFrameProbe ? performance.now() : 0;
    this._frame(dt);
    if (this._rangeFrameProbe) this._rangeFrameProbe.record(frameStart, performance.now()-frameStart, {
      frameRateHz: capHz || this._iwRefreshProbe?.rate || 60,
      refreshHz: this._iwRefreshProbe?.rate || 0,
      scale: this.R?.dynScale || 1,
      phase: this.match?.range || this.match?.opts?.range ? 'practice' :
        this.match?.attract ? 'attract' : this.match ? 'battle' : 'menu',
      stages: this.perf,
    });
  }

  // keep weaker GPUs playable: when a window of a live round averages under the target, drop render density one notch.
  // Stepping back up needs three windows of real headroom and a cool-down that doubles every time an up-step had to be
  // taken back, so a device that only hitched once (a GC, a burst of splats) gets its sharp image back, while one that
  // truly sits at the edge settles instead of pumping between sizes (re-sizing every few seconds reads as flicker).
  _dynRes(dt) {
    if (this.match?.paused && !this.match.attract && !G.netm) return;
    if (dt <= 0 || dt > 0.25) return;
    const d = this._dyn || (this._dyn = {
      acc: 0, n: 0, t: 0, good: 0, cooldown: 0, failures: 0, probe: false,
      match: null, quality: null,
    });
    const match = this.match;
    const quality = this.settings.quality;
    // A new match/quality starts with fresh history. Keep the current scale; stable headroom can recover it.
    if (d.match !== match || d.quality !== quality) {
      d.acc = 0; d.n = 0; d.t = 0; d.good = 0; d.cooldown = 0; d.failures = 0; d.probe = false;
      d.match = match; d.quality = quality;
    }
    d.acc += dt; d.n++; d.t += dt;
    if (d.t < 4) return;
    const avg = d.acc / Math.max(1, d.n);
    d.acc = 0; d.n = 0; d.t = 0;

    const live = quality !== 'ultra' && !document.hidden && match && !match.attract && match.state === 'playing';
    if (!live) { d.good = 0; d.probe = false; return; }
    if (d.cooldown > 0) d.cooldown--;

    const s = this.R.dynScale || 1;
    const floor = this.mobile?.touch ? 0.6 : 0.75;
    // Hysteresis around the 60 Hz budget: degrade below ~50 fps, recover only after ~58+ fps is stable.
    // Compare against the actually selected evenly paced Auto cap; otherwise
    // intentional 45Hz on a 90Hz panel is misdiagnosed as GPU overload and
    // permanently drops texture resolution to its minimum.
    const budget = dynamicResolutionBudget(this.settings.frameRate === 'auto'
      && this.mobile?.touch ? this._iwLastCap : 60);
    const overloaded = avg > budget.overloadFrameSeconds;
    const headroom = avg < budget.headroomFrameSeconds;

    if (overloaded && s > floor + 0.01) {
      if (d.probe) {
        d.failures = Math.min(3, d.failures + 1);
        d.cooldown = Math.min(8, 1 << d.failures); // 8 s, 16 s, 32 s between failed recovery probes
      }
      this.R.setDynamicScale(Math.max(floor, s - 0.125));
      d.good = 0; d.probe = false;
      return;
    }

    if (headroom && s < 0.99 && d.cooldown === 0) {
      if (++d.good >= 3) {
        this.R.setDynamicScale(Math.min(1, s + 0.125));
        d.good = 0;
        d.probe = true;
      }
    } else if (!headroom) {
      d.good = 0;
    }

    if (d.probe && headroom && s >= 0.99) {
      d.probe = false;
      d.failures = Math.max(0, d.failures - 1);
    }
  }

  _frame(dt) {
    if (this._nativeStageSwitchPending) {
      G.time += Math.max(0, dt);
      this.input?.pollPad?.();
      this._padMenus?.(dt);
      G.net?.update?.(dt);
      this.menus?.update?.(dt);
      this.input?.endFrame?.();
      this.s3Clock?.reset?.();
      return;
    }
    const artScreen = this.menus?._scr?.name;
    if (G.mode === 'menu' && this.match?.attract &&
        INKWAVE_ART_MENU_SCREENS.has(artScreen) && INKWAVE_ART_MENU_SCREENS.has(this.menus?.current)) {
      // Nothing of the demo world stays on screen behind the art: hide the
      // canvas so the compositor stops blending a stale full-screen frame.
      const artCanvas = G.renderer?.domElement, hideCanvas = artScreen !== 'locker';
