      // including a full-screen pause screenshot retained by a just-quit battle.
      // The lazy composer recreates its targets before the next real 3D frame.
      this.R?.releasePausedFrame?.();
      this.R?.composer?.releaseInactiveTargets?.();
      if (artScreen !== 'locker') this.showcase?.retireHiddenStudio?.(dt);
      if (artScreen !== 'locker' && this.showcase?._rt) {
        this.showcase._rt.dispose(); this.showcase._rt = null;
      }
      // Character thumbnails are still generated only when requested. No
      // showcase/world render loop runs behind these decorative backgrounds.
      if (this.showcase?._pq?.length) this.showcase._portraitStep?.();
      // The locker keeps its live pedestal kid, drawn over the same art.
      if (artScreen === 'locker' && this.showcase && G.renderer) renderInkwaveLockerStage(this, G, dt);
      this.menus.update(dt);
      this.input.endFrame();
      return;
    }
    if (this._artCanvasHidden) { G.renderer.domElement.style.visibility = ''; this._artCanvasHidden = false; }
    const tA = performance.now();
    G.renderer.info.reset();
    const m = this.match;
    const setUp = !!this.showcase?.fullFrame;
    const portraitFrame=syncPortraitFrame(this,G);
    if (!portraitFrame.offline) runSimulation(this, portraitFrame.released ? 0 : dt);
    const resultsQuiet = this.match?.state === 'results';
    // A full-frame lobby/showcase completely covers the arena. Keep input/net/audio/showcase alive, but suspend
    // hidden-world visual work (FX, environment, decor, paint atlas, game camera) until the arena is visible again.
    const pausedFrame = pausedWorldFrame(this, G);
    if (!pausedFrame.paused) this.R?.releasePausedFrame?.();
    const menuAttractBudget = idleAttractMenuBudget(this, G);
    const worldHidden = setUp || document.hidden || pausedFrame.paused || (menuAttractBudget && !this._menuAttractFrame);
    const worldDt = menuAttractBudget ? this._menuAttractFrameDelta : dt;
    const loc = m?.local;
    if (!worldHidden) {
      if (!m || (!m.paused && !resultsQuiet)) G.fx.update(worldDt, G.camera);
      if (!m || (!m.paused && !resultsQuiet)) { this.fxHooks?.update?.(worldDt); updateSplatGhosts(G, worldDt); }
      this.screenfx?.update?.(worldDt, this);
      G.env.update?.(worldDt, G.camera);
      this.decor.update(worldDt);
      this.props?.update?.(worldDt, G.time);
      // map diorama: held map key during live play (or while waiting to respawn) swoops the view overhead
      this.rig.setMap?.(!!(m && !m.attract && !m.paused && m.state === 'playing' && m.controller?.mapHeld && !this.menus?.current));
