    }

    // --- low HP heartbeat (lub-dub, faster when lower)
    const hp = alive ? clamp(a.hp / 100, 0, 1) : 1;
    const lowK = alive ? clamp((0.5 - hp) / 0.38, 0, 1) : 0;
    s.hurt = damp(s.hurt, lowK, 4, dt);
    if (lowK > 0) {
      const bpm = 80 + 70 * lowK;
