    s.satPop = Math.max(0, s.satPop - dt * 2.2);

    // --- one-shots decay
    s.kill = Math.max(0, s.kill - dt * 2.4);
    s.flash = Math.max(0, s.flash - dt * (s.flash > 0.6 ? 4.5 : 2.6));
    s.chroma = Math.max(0, s.chroma - dt * 3.2);
    s.blast = Math.max(0, s.blast - dt * 2.4);
    s.blastT += dt;
