  }

  dispose() {
    if (this._disposed) return;
    this._disposed = true;
    for (const off of this._unsubs) off();
    this._unsubs.length = 0;
    if (this.G.screenfx === this) this.G.screenfx = null;
    if (this.R.extraPass === this.pass) this.R.setExtraPass(null);
    this.lens.dispose(); this.mat.dispose();
  }
}
